var i=`0735-molho-no-fogo`;var t=`world-0735`;var o=`ST`;var a=`central-africa`;var s=4;var r=64;var g={en:`Molho no Fogo`,ua:`Молью ну фогу`};var l={en:`Molho no Fogo is a São Tomé and Príncipe classic prepared with chicken thigh, yellow onion, tomato, eggplant. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Молью ну фогу, страва кухні країни Сан-Томе і Принсіпі зі складниками: куряче стегно, жовта цибуля, помідор, баклажан. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var h=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`chicken-thigh`,670,`g`],[`yellow-onion`,190,`g`],[`sunflower-oil`,40,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 48 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 48 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:48,i:[[`tomato`,330,`g`],[`eggplant`,250,`g`],[`water`,620,`ml`],[`hot-paprika`,5,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,18,`g`],[`lemon-juice`,20,`ml`]]}];var m={slug:i,id:t,country:`ST`,region:a,servings:4,minutes:64,title:g,text:l,steps:h};export{o as country,m as default,t as id,r as minutes,a as region,s as servings,i as slug,h as steps,l as text,g as title};